    /// <summary>The bidi class of one code point (UAX #44's bidirectional_category).</summary>
    public static Bidi.BidiClass ClassOf(int codePoint)
    {
        var lo = 0;
        var hi = ClassRanges.Length - 1;
        while (lo <= hi)
        {
            var mid = (lo + hi) / 2;
            var range = ClassRanges[mid];
            if (codePoint < range.Start) hi = mid - 1;
            else if (codePoint > range.End) lo = mid + 1;
            else return range.Class;
        }
        return Bidi.BidiClass.L;
    }
}
